create table if not exists public.daily_feature_usage (user_id uuid not null references auth.users(id) on delete cascade, feature_code text not null check (feature_code in ('headswap')), usage_date date not null, usage_count integer not null default 0 check (usage_count >= 0), updated_at timestamptz not null default now(), primary key(user_id, feature_code, usage_date)); alter table public.daily_feature_usage enable row level security; create policy "members read own daily feature usage" on public.daily_feature_usage for select to authenticated using (auth.uid()=user_id); grant select on public.daily_feature_usage to authenticated;